import json,hashlib,collections
from pathlib import Path
R=Path(__file__).resolve().parent;P=R.parent;rows=[]
localpath=P/'probability_500_20261012/results/pairs.json';apipath=P/'api_results_20261015/results/matched_results.json'
for r in json.load(open(localpath)):
 for policy in ['joint','fixed50']:
  row=dict(model=r['judge'],backbone=r['backbone'],dataset=r['dataset'],policy=policy,scope='local full-test study')
  for c in ['baseline','saliency','nearest']:
   v=r['variants'][c+'_'+policy];row[c]=dict(probe=v['probe_threshold'],judge=v['probability_threshold'])
  rows.append(row)
api=collections.defaultdict(dict)
for r in json.load(open(apipath)):
 if r['scope']!='api_condition_matched' or r['policy'] not in ['joint','fixed50']:continue
 k=r['model'],r['backbone'],r['dataset'],r['policy'];api[k][r['condition']]=dict(probe=r['probe_threshold'],judge=r['probability_threshold'])
for (m,b,d,pol),v in api.items():assert len(v)==3;rows.append(dict(model=m,backbone=b,dataset=d,policy=pol,scope='API condition-matched valid cases',**v))
assert len(rows)==1000 and len({(r['model'],r['backbone'],r['dataset'],r['policy']) for r in rows})==1000
rows.sort(key=lambda r:(r['model'],r['backbone'],r['dataset'],r['policy']))
(R/'thresholds.json').write_text(json.dumps(rows,indent=2))
summary=[]
for m in sorted({r['model'] for r in rows}):
 rr=[r for r in rows if r['model']==m and r['policy']=='joint'];summary.append(dict(model=m,cells=50,**{c:sum(r[c]['judge']==0 for r in rr) for c in ['baseline','saliency','nearest']}))
(R/'summary.json').write_text(json.dumps(summary,indent=2))
raw=json.dumps(rows,ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html><head><meta charset="utf-8"><title>All original probe and judge thresholds</title><style>body{font:15px system-ui;margin:30px;color:#182332}h1{font-size:25px}select,input,button{font:inherit;margin:5px;padding:7px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border:1px solid #ddd;padding:8px;text-align:right}td:first-child,td:nth-child(2),td:nth-child(3){text-align:left}thead{position:sticky;top:0;background:#e9eef3}td.zero{background:#ffd6cc;color:#8a2300;font-weight:bold}tbody tr:nth-child(even){background:#f7f9fb}.note{max-width:1100px;line-height:1.5}.controls{position:sticky;top:0;background:white;padding:8px 0}#counts{font-weight:bold;margin:15px 0}.tablewrap{max-height:70vh;overflow:auto}a{color:#1966b3}</style></head><body><h1>All original probe and judge thresholds</h1><p class="note">Exact saved thresholds from the core probability-output study. No re-tuning. Each row is one judge × backbone × dataset; each explanation has its own probe and judge threshold. Probe probabilities are on 0–1; judge scores are on 0–100. Positive requires probe ≥ its cutoff AND judge score ≥ its cutoff. <strong>Red zero cells bypass the judge.</strong> A positive cutoff can also have no practical vetoes; this table shows thresholds, not observed veto counts.</p><p class="note">Six local models use their original full-test-study policies. Four API models use their own condition-matched valid-response policies. All thresholds were selected using validation. These are distinct analysis cohorts. Common-valid-all-judges sensitivity policies are not mixed into this inventory.</p><div class="controls"><label>Policy <select id="policy"><option value="joint">Joint validation tuning</option><option value="fixed50">Judge fixed at 50; probe validation tuned</option></select></label><label>Judge <select id="model"><option value="">All</option></select></label><label>Backbone <select id="backbone"><option value="">All</option></select></label><label>Dataset <select id="dataset"><option value="">All</option></select></label><label><input type="checkbox" id="zero">Only rows containing a zero judge cutoff</label><label><input type="checkbox" id="precise" checked>Full precision</label><button onclick="download()">Download exact thresholds JSON</button></div><div id="counts"></div><div class="tablewrap"><table><thead><tr><th rowspan="2">Judge</th><th rowspan="2">Backbone</th><th rowspan="2">Dataset</th><th colspan="2">No explanation</th><th colspan="2">Saliency</th><th colspan="2">1 NN</th></tr><tr><th>Probe (0–1)</th><th>Judge (0–100)</th><th>Probe (0–1)</th><th>Judge (0–100)</th><th>Probe (0–1)</th><th>Judge (0–100)</th></tr></thead><tbody id="body"></tbody></table></div><p class="note">Aliases: qwen = Qwen27B judge; gemma = Gemma31B judge; mistral = MistralSmall4 119B; olmo = OLMo3.1 32B; glm = GLM4.7Flash; qwen122 = Qwen3.5 122B. API names are the recorded aliases, not independently verified backend versions. Backbone aliases are those in the frozen experiment artifacts.</p><script>const rows=DATA;const conditions=['baseline','saliency','nearest'];for(const k of ['model','backbone','dataset']){const s=document.getElementById(k);for(const v of [...new Set(rows.map(r=>r[k]))].sort()){const o=document.createElement('option');o.value=v;o.textContent=v;s.appendChild(o)}}function selected(){return rows.filter(r=>r.policy===document.getElementById('policy').value&&['model','backbone','dataset'].every(k=>!document.getElementById(k).value||r[k]===document.getElementById(k).value)&&(!document.getElementById('zero').checked||conditions.some(c=>r[c].judge===0)))}function render(){const data=selected();const n=data.reduce((s,r)=>s+conditions.filter(c=>r[c].judge===0).length,0);document.getElementById('counts').textContent=`${data.length} rows · ${data.length*3} threshold pairs · ${n} zero judge cutoffs (${data.length?(100*n/(data.length*3)).toFixed(1):0}%)`;const tbody=document.getElementById('body');tbody.replaceChildren();for(const r of data){const tr=document.createElement('tr');for(const k of ['model','backbone','dataset']){const td=document.createElement('td');td.textContent=r[k];tr.appendChild(td)}for(const c of conditions){for(const k of ['probe','judge']){const td=document.createElement('td');td.textContent=k==='probe'&&!document.getElementById('precise').checked?r[c][k].toFixed(6):String(r[c][k]);td.title=String(r[c][k]);if(k==='judge'&&r[c][k]===0)td.className='zero';tr.appendChild(td)}}tbody.appendChild(tr)}}function download(){const blob=new Blob([JSON.stringify(selected(),null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='original_thresholds.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}document.querySelectorAll('select,input').forEach(e=>e.addEventListener('change',render));render();</script></body></html>'''.replace('DATA',raw)
(R/'report.html').write_text(page)
(R/'VERIFIED.json').write_text(json.dumps(dict(rows=len(rows),threshold_pairs=3000,joint_rows=500,joint_threshold_pairs=1500,joint_zero=sum(sum(r[c]['judge']==0 for c in ['baseline','saliency','nearest']) for r in rows if r['policy']=='joint'),inputs={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [localpath,apipath]}),indent=2))
print(json.dumps(summary,indent=2))
